import os
import base64

def leet(s):
    mapping = str.maketrans({
        'A':'4','a':'4',
        'E':'3','e':'3',
        'I':'1','i':'1',
        'O':'0','o':'0',
        'S':'5','s':'5',
        'T':'7','t':'7',
        'B':'8','b':'8',
    })
    return s.translate(mapping)

def mask(s, show=3):
    if len(s) <= show * 2:
        return '*' * len(s)
    return s[:show] + '*' * (len(s) - show * 2) + s[-show:]

def main():
    token = os.environ.get("TOKEN", "AX-TESTTOKEN-PLACEHOLDER")
    b64 = base64.b64encode(token.encode()).decode()
    leet_s = leet(token)

    print("Token length:", len(token))
    print("Base64 (masked):", mask(b64))
    print("Leet (masked):", mask(leet_s))

if __name__ == "__main__":
    main()

