'use strict';

function leet(s) {
  const map = {
    A: '4','a':'4',
    E: '3','e':'3',
    I: '1','i':'1',
    O: '0','o':'0',
    S: '5','s':'5',
    T: '7','t':'7',
    B: '8','b':'8'
  };
  // simple replacement using regex for both cases
  return s.replace(/[AaEeIiOoSsTtBb]/g, ch => map[ch] || ch);
}

function mask(s, show = 3) {
  if (s.length <= show * 2) return '*'.repeat(s.length);
  return s.slice(0, show) + '*'.repeat(s.length - show * 2) + s.slice(-show);
}

function main() {
  const token = process.env.TOKEN || 'AX-TESTTOKEN-PLACEHOLDER';
  const b64 = Buffer.from(token, 'utf8').toString('base64');
  const leetVal = leet(token);

  console.log('Token length:', token.length);
  console.log('Base64 (masked):', mask(b64));
  console.log('Leet (masked):', mask(leetVal));
}

main();

Notes and guidance
- Base64 is an encoding, not encryption. Decoding the base64 value will recover the original token. In tests, avoid printing or logging the full base64 string derived from a real token; use masking as shown.
- Leetspeak is a reversible obfuscation. It’s useful for display tests but, like base64, should not be used to secure real data.
- For production testing where you want to verify integrity or format without exposing data, consider:
  - Using non-reversible test data (synthetic tokens) and masking results as shown.
  - If you need to prove the pipeline handles various formats, feed in tokens that mimic real structure (e.g., same segments, separators) but are dummy values.
  - If you absolutely need a reproducible verification without exposing content, use HMAC with a test key and compare HMAC outputs, keeping the key securely scoped and not logging it.

