import os
import hashlib
import hmac
import base64

def main():
    token = os.environ.get("TOKEN", "AX-TESTTOKEN-PLACEHOLDER")
    salt = b"tester-salt-01"  # use a test salt
    sha_digest = hashlib.sha256(salt + token.encode()).hexdigest()

    # HMAC with a test key
    test_key = b"TEST_KEY_12345"
    mac = hmac.new(test_key, token.encode(), hashlib.sha256).hexdigest()

    # Numeric representation: ASCII codes
    ascii_codes = ' '.join(str(b) for b in token.encode())

    # Optional base64 of the SHA digest
    sha_base64 = base64.b64encode(bytes.fromhex(sha_digest)).decode()

    print("SHA-256(salt+token) hex:", sha_digest)
    print("SHA-256(salt+token) base64:", sha_base64)
    print("HMAC-SHA256 hex:", mac)
    print("ASCII codes:", ascii_codes)

if __name__ == "__main__":
    main()

