const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function rot13(s) {
  // Simple ROT13 for A-Z/a-z
  return s.replace(/[A-Za-z]/g, function(ch) {
    const base = (ch >= 'a' && ch <= 'z') ? 97 : 65;
    return String.fromCharCode(((ch.charCodeAt(0) - base + 13) % 26) + base);
