  fs.mkdirSync(outputDir, { recursive: true });
  const outPath = path.join(outputDir, 'rot13_token.txt');
  fs.writeFileSync(outPath, rotated, { mode: 0o600 });
  console.log('ROT13 computed; length:', rotated.length);
  console.log('ROT13 digest (for verification):', digest);
