import os
import string
import random
import hashlib

def generate_mapping(seed):
    letters = list(string.ascii_uppercase)
    rnd = random.Random(seed)  # deterministic from seed
    perm = letters[:]
    rnd.shuffle(perm)
    encode_map = {letters[i]: perm[i] for i in range(26)}
    decode_map = {perm[i]: letters[i] for i in range(26)}
    return encode_map, decode_map

def encode_token(token, encode_map):
    out = []
    for ch in token:
        if ch.isalpha():
            if ch.isupper():
                out.append(encode_map.get(ch, ch))
            else:
                upper = ch.upper()
                mapped = encode_map.get(upper, upper)
                out.append(mapped.lower())
        else:
            out.append(ch)
    return ''.join(out)

def decode_token(encoded, decode_map):
    out = []
    for ch in encoded:
        if ch.isalpha():
            if ch.isupper():
                out.append(decode_map.get(ch, ch))
            else:
                upper = ch.upper()
                mapped = decode_map.get(upper, upper)
                out.append(mapped.lower())
        else:
            out.append(ch)
    return ''.join(out)

def main():
    token = os.environ.get("TOKEN", "AX-TESTTOKEN-PLACEHOLDER")
    seed = os.environ.get("SEED", "CI_TEST_SEED_ABC123")
    encode_map, decode_map = generate_mapping(seed)
    encoded = encode_token(token, encode_map)
    digest = hashlib.sha256(encoded.encode()).hexdigest()
    print("Encoded token (preview):", encoded[:32] + ("..." if len(encoded) > 32 else ""))
    print("Encoded length:", len(encoded))
    print("SHA-256(encoded):", digest)
    print("Decoded equals original:", decode_token(encoded, decode_map) == token)

if __name__ == "__main__":
    main()

