'use strict';
const crypto = require('crypto');

function stringToSeed(str) {
  // Simple 32-bit hash-like seed from string
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (h * 31 + str.charCodeAt(i)) | 0;
  }
  return h >>> 0;
}

// Simple deterministic RNG (Mulberry32)
function mulberry32(a) {
  return function() {
    let t = (a += 0x6D2B79F5) >>> 0;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildMapping(seed) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const rng = mulberry32(seed);
  const perm = alphabet.split('');
  for (let i = perm.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [perm[i], perm[j]] = [perm[j], perm[i]];
  }
  const encodeMap = {};
  const decodeMap = {};
  for (let i = 0; i < 26; i++) {
    encodeMap[alphabet[i]] = perm[i];
    decodeMap[perm[i]] = alphabet[i];
  }
  return { encodeMap, decodeMap };
}

function encodeToken(token, map) {
  return token.split('').map(ch => {
    if (/[A-Za-z]/.test(ch)) {
      const isLower = ch === ch.toLowerCase();
      const base = isLower ? 'a' : 'A';
      const upper = ch.toUpperCase();
      const mapped = map[upper] || upper;
      return isLower ? mapped.toLowerCase() : mapped;
    } else {
      return ch;
    }
  }).join('');
}

function decodeToken(encoded, map) {
  return encoded.split('').map(ch => {
    if (/[A-Za-z]/.test(ch)) {
      const isLower = ch === ch.toLowerCase();
      const upper = ch.toUpperCase();
      const mapped = map[upper] || upper;
      const orig = mapped;
      // map back using inverse (map is already inverse in decode path)
      return isLower ? orig.toLowerCase() : orig;
    } else {
      return ch;
    }
  }).join('');
}

function main() {
  const token = process.env.TOKEN || 'AX-TESTTOKEN-PLACEHOLDER';
  const seedStr = process.env.SEED || 'CI_TEST_SEED_ABC123';
  const seed = stringToSeed(seedStr);
  const { encodeMap, decodeMap } = buildMapping(seed);
  const encoded = encodeToken(token, encodeMap);
  const digest = crypto.createHash('sha256').update(encoded).digest('hex');
  console.log('Encoded (preview):', encoded.substring(0, 32) + (encoded.length > 32 ? '...' : ''));
  console.log('Encoded length:', encoded.length);
  console.log('SHA-256(encoded):', digest);
  const decoded = decodeToken(encoded, decodeMap);
  console.log('Decoded equals original:', decoded === token);
}

main();

